const $=s=>document.querySelector(s);let size='M',cart=[];const cartDialog=$('#cart');
document.querySelectorAll('[data-size]').forEach(b=>b.addEventListener('click',()=>{size=b.dataset.size;document.querySelectorAll('[data-size]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b))})}));
function renderCart(){ $('#count').textContent=`(${cart.reduce((n,p)=>n+p.qty,0)})`;const items=$('#cart-items');items.replaceChildren();if(!cart.length){const p=document.createElement('p');p.textContent='Tu bolsa está vacía. Explora la colección.';items.append(p)}cart.forEach(p=>{const row=document.createElement('div');row.className='cart-row';const text=document.createElement('p');text.textContent=`Hoodie / Black — Talla ${p.size} · Cantidad: ${p.qty} · Precio por confirmar`;const remove=document.createElement('button');remove.textContent='Quitar';remove.setAttribute('aria-label',`Quitar talla ${p.size}`);remove.onclick=()=>{cart=cart.filter(x=>x.size!==p.size);$('#checkout-message').textContent='';renderCart()};row.append(text,remove);items.append(row)});$('#checkout').disabled=!cart.length;}
let toastTimer;$('#add').onclick=()=>{const item=cart.find(p=>p.size===size);if(item)item.qty++;else cart.push({size,qty:1});$('#checkout-message').textContent='';renderCart();$('#toast').textContent=`Hoodie talla ${size} agregada a la bolsa`;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2500)};
$('#bag').onclick=()=>{renderCart();cartDialog.showModal()};$('#product-open').onclick=()=>$('#product-modal').showModal();document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close').onclick=()=>d.close();d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})});$('#checkout').onclick=()=>{$('#checkout-message').textContent='Prueba completada. No se creó ningún pedido ni se realizó ningún cobro. Para vender será necesario confirmar precios, inventario y conectar una pasarela de pagos.'};$('#motion').onclick=()=>{const paused=document.body.classList.toggle('paused');$('#motion').textContent=paused?'Reanudar movimiento ▶':'Pausar movimiento ⏸';$('#motion').setAttribute('aria-pressed',String(paused))};if(matchMedia('(prefers-reduced-motion: reduce)').matches){$('#motion').hidden=true}renderCart();
